from pathlib import Path
import asyncio,json,hashlib,time,sys
sys.path.insert(0,'/Users/jangwook/workspace/life-manager-v2/src')
from lm.gateway.providers.codex import CodexProvider
from lm.gateway.types import ChatRequest,Message
OUT=Path(__file__).parent;src=json.loads((OUT/'translation-input.json').read_text())
async def one(lang,name):
 data=({k:src[k] for k in ['metadata','body','prompt']} if name=='article' else {k:src[k] for k in ['figures','labs','script_texts']})
 instruction=f'''Translate this approved Korean chapter06 WCAG2.2 SC1.2.4 Captions(Live), AA material directly into { {'en':'English','ja':'Japanese','zh':'Simplified Chinese'}[lang]}. Return one valid complete JSON object with the SAME keys, array sizes, nesting, no omissions/summaries/new claims or markdown wrapper. For article: translate title, summary, full body and prompt including all YAML and JSON examples HUMAN-readable values, placeholders, requested output language. Preserve JSON schema KEYS and ENUMS exactly, code syntax, criterion numbers, IDs L01–L12, exact evidence values/times, all conditional premises, negation, alternative-caption-path logic, normative vs informative distinctions, pure-audio caveat, no fixed latency threshold, actual_supplied_evidence vs hypothetical_supplied_scenario and not_assessed, separate P1 plans3 vs36 separate fresh single-case contexts (12cases repeated3times), scope/limits (NOT actual live broadcast or direct audio/video processing). Preserve every link, HTML/Markdown structure; importer localizes only internal URLs. Do NOT claim translated prompt/fixture copies were independently executed. No drafting/revision history. For assets: translate every figure title/desc, labels nested line-by-line preserving all dimensions/count/order and coherent meaning across adjacent lines; keep labels COMPACT to fit existing boxes, abbreviate naturally without loss of negation. Translate lab visible texts, aria names and script_texts strings only; do not translate identifiers or raw original evidence JSON. Add source_notice (one concise sentence): replayed original video audio/screen text remain Korean; page and caption controls are localized. For generated demo all canvas text is translated. This task is translation of an approved Argon-written source, using prior publication translator settings; no new article authoring or experiment. Input JSON:\n'''+json.dumps(data,ensure_ascii=False)
 (OUT/f'{lang}-{name}-input.txt').write_text(instruction);provider=CodexProvider();start=time.time()
 try:
  result=await provider.chat(ChatRequest(messages=[Message(role='system',content='Careful technical translator. Complete valid JSON only. Preserve evidence boundaries and every condition.'),Message(role='user',content=instruction)],model='gpt-6.1-sol',timeout_sec=1500,extra={'reasoning_effort':'medium'}))
  (OUT/f'{lang}-{name}-raw.txt').write_text(result.text);parsed=json.loads(result.text);(OUT/f'{lang}-{name}.json').write_text(json.dumps(parsed,ensure_ascii=False,indent=2));(OUT/f'{lang}-{name}-receipt.json').write_text(json.dumps({'requested_model':'gpt-6.1-sol','returned_model':result.model,'provider':result.provider,'requested_effort':'medium','elapsed_seconds':round(time.time()-start,2),'finish_reason':result.finish_reason,'input_sha256':hashlib.sha256(instruction.encode()).hexdigest(),'output_sha256':hashlib.sha256(result.text.encode()).hexdigest()},indent=2));print(lang,name,'complete',flush=True)
 finally:await provider._client.aclose()
async def main():await asyncio.gather(*(one(lang,name) for lang in ['en','ja','zh'] for name in ['article','assets']))
asyncio.run(main())
